<?php
/** Proof — record, submit (spec "Proof", 1): Priya records a 120.00 meal with a JPEG from the camera field (stored under storage/attachments/expense/<id>/, the mime from finfo, served inline with nosniff); EXP-000001 in USD with the 10 % policy markup → 132.00; Save and submit without the file → the threshold's sentence; with it → submitted; a 40.00 coffee on the company card submits without a receipt and is not reimbursable. */
require __DIR__ . '/lib.php';
[$acme, $beta] = expense_world();
$priya = as_member(26); $marco = as_member(27); $dana = as_member(30);
$meals = category('meals'); $num = (string) one('SELECT number FROM engagements WHERE id = :e', ['e' => $acme]);

echo "1. The camera first: a 120.00 meal with its receipt\n";
$since = last_activity_id();
$jpg = jpeg_file();
[$c, $b] = upload($priya, '/expenses/save.php', ['engagement' => $acme, 'date' => date('Y-m-d'), 'category' => $meals, 'amount' => '120.00', 'tax_amount' => '9.00', 'vendor_name' => 'SMOKE Bistro', 'description' => 'SMOKE client dinner'], 'file', $jpg, 'dinner.jpg');
$e1 = (int) ($b['record_id'] ?? 0);
ok($c === 200 && $e1 > 0 && ($b['location'] ?? '') === '/expenses/' . $e1 . '?notice=saved' && $b['number'] === 'EXP-000001' && $b['status'] === 'draft' && ($b['refresh'] ?? '') === 'expenseChanged', 'expense_save with the camera file: 200, record_id ' . $e1 . ', EXP-000001, a draft, lands on the record (' . ($b['did'] ?? msg($b)) . ')');
$x = expense_row($e1);
ok($x['number'] === 'EXP-000001' && $x['currency'] === 'USD' && $x['amount'] === '120.00' && $x['tax_amount'] === '9.00' && $x['markup_pct'] === '10.00' && $x['billable_amount'] === '132.00' && $x['paid_with'] === 'personal' && $x['reimbursable'] === true && $x['billable'] === true && (int) $x['member_id'] === 26 && (int) $x['created_by'] === 26, 'the database made it: USD from the engagement, the 10 % policy markup → 132.00, personal card → reimbursable, billable by the category\'s default');
$a = q("SELECT * FROM attachments WHERE record_type = 'expense' AND record_id = :e", ['e' => $e1]);
ok(count($a) === 1 && $a[0]['mime_type'] === 'image/jpeg' && $a[0]['filename'] === 'dinner.jpg' && str_starts_with($a[0]['storage_path'], 'attachments/expense/' . $e1 . '/') && is_file(dirname(__DIR__, 3) . '/storage/' . $a[0]['storage_path']) && (int) $a[0]['uploaded_by'] === 26, 'the receipt is an attachment of the expense: image/jpeg from finfo, under storage/attachments/expense/' . $e1 . '/, uploaded by Priya');
ok($a[0]['client_visible'] === true, 'it follows the engagement\'s sharing: the settings default (share receipts) → client-visible');
$aid = (int) $a[0]['id'];
$r = req('GET', '/attachments/' . $aid, ['jar' => $priya]);
ok($r['code'] === 200 && stripos($r['headers'], 'Content-Type: image/jpeg') !== false && stripos($r['headers'], 'X-Content-Type-Options: nosniff') !== false && stripos($r['headers'], 'Content-Disposition: inline') !== false, 'served through the gate: image/jpeg, inline, nosniff');
$r2 = req('GET', '/expenses/attachments/get.php?id=' . $aid, ['jar' => $priya]);
ok($r2['code'] === 200 && $r2['body'] === $r['body'] && stripos($r2['headers'], 'nosniff') !== false, '/expenses/attachments/get.php is the same door');
ok(req('GET', '/attachments/' . $aid)['code'] === 302, 'nobody signed in: sent to the launcher');
$log = activity('expense.save', $since);
$after = json_decode((string) $log[0]['after'], true);
ok(count($log) === 1 && (int) $log[0]['engagement_id'] === $acme && $log[0]['entity_type'] === 'expense' && (int) $log[0]['entity_id'] === $e1 && $after['amount'] === '120.00' && $after['currency'] === 'USD' && $after['number'] === 'EXP-000001' && $after['recorded_by'] === 26 && $after['category_id'] === $meals && $after['paid_with'] === 'personal' && $after['billable'] === true && $after['markup_pct'] === '10.00', 'expense.save logged with engagement_id, amount, currency, category_id, paid_with, billable, markup_pct, recorded_by');
$att = activity('expense.attach', $since);
$ad = json_decode((string) $att[0]['after'], true);
ok(count($att) === 1 && $ad['filename'] === 'dinner.jpg' && $ad['mime_type'] === 'image/jpeg' && (int) $att[0]['engagement_id'] === $acme && !str_contains((string) $log[0]['after'], 'Bistro') && !str_contains((string) $log[0]['after'], 'dinner'), 'expense.attach logged (filename, mime); no vendor or description text in the save');
[$c, $d] = screen($priya, '/expenses/' . $e1);
ok($c === 200 && $d['expense']['has_receipt'] === true && $d['expense']['receipt']['url'] === '/attachments/' . $aid && $d['expense']['billable_amount'] === '132.00' && $d['expense']['receipt_needed'] === false && $d['may']['submit'] === true && $d['may']['approve'] === false && count($d['receipts']) === 1, 'the record\'s JSON: the receipt, 132.00, may submit, may not approve');

echo "2. Save and submit: the receipt rule is the database's\n";
$count = (int) one('SELECT count(*) FROM expenses');
[$c, $b] = record_expense($priya, $acme, '120.00', ['submit' => '1']);
ok($c === 422 && msg($b) === 'A receipt is required at or above 75.00 — attach one to submit EXP-000002', 'Save and submit without the file: the threshold\'s sentence (' . msg($b) . ')');
ok((int) one('SELECT count(*) FROM expenses') === $count && (string) one("SELECT number FROM expenses ORDER BY id DESC LIMIT 1") === 'EXP-000001', 'and nothing was saved: all or nothing (no duplicate on a retry, the numbering has no gap)');
[$c, $b] = act($priya, '/expenses/submit.php', ['expense' => $e1]);
ok($c === 200 && $b['status'] === 'submitted' && expense_row($e1)['status'] === 'submitted' && expense_row($e1)['submitted_at'] !== null, 'submit.php on the draft with the receipt: submitted');
$told = q("SELECT member_id, kind, record_type, record_id FROM notifications WHERE kind = 'expense_submitted' ORDER BY id DESC LIMIT 1");
ok($told === [['member_id' => 27, 'kind' => 'expense_submitted', 'record_type' => 'expense', 'record_id' => $e1]], 'Marco (the engagement\'s manager) is told in-app, the notice about the expense');
$sub = activity('expense.submit', $since);
ok(count($sub) === 1 && (int) $sub[0]['engagement_id'] === $acme && json_decode((string) $sub[0]['after'], true)['amount'] === '120.00' && json_decode((string) $sub[0]['after'], true)['currency'] === 'USD', 'expense.submit logged with the amount and the currency');
[$c, $b] = act($priya, '/expenses/submit.php', ['expense' => $e1]);
ok($c === 422 && msg($b) === 'Expense EXP-000001 is already submitted', 'submitting twice: the verb\'s words');
$jpg = jpeg_file();
$since2 = last_activity_id();
[$c, $b] = upload($priya, '/expenses/save.php', ['engagement' => $beta, 'date' => date('Y-m-d'), 'category' => category('travel'), 'amount' => '90.00', 'description' => 'SMOKE train', 'submit' => '1'], 'file', $jpg, 'train.jpg');
$e3 = (int) ($b['record_id'] ?? 0);
ok($c === 200 && $b['status'] === 'submitted' && expense_row($e3)['status'] === 'submitted' && str_starts_with((string) $b['did'], 'Recorded and submitted EXP-000002'), 'Save and submit WITH the file on Beta: recorded and submitted in one request (' . ($b['did'] ?? msg($b)) . ')');
ok(count(activity('expense.save', $since2)) === 1 && count(activity('expense.attach', $since2)) === 1 && count(activity('expense.submit', $since2)) === 1, 'one save, one attach and one submit row for it');
$coffee = record_expense($priya, $acme, '40.00', ['paid_with' => 'company_card', 'description' => 'SMOKE coffee', 'submit' => '1']);
$e2 = (int) ($coffee[1]['record_id'] ?? 0);
$x2 = expense_row($e2);
ok($coffee[0] === 200 && $x2['status'] === 'submitted' && $x2['paid_with'] === 'company_card' && $x2['reimbursable'] === false && (bool) one('SELECT ct_expense_has_receipt(:e)', ['e' => $e2]) === false, 'a 40.00 coffee on the company card submits without a receipt (under the threshold) and is not reimbursable');

echo "3. Fields and the database's other rules\n";
[$c, $b] = act($priya, '/expenses/save.php', ['engagement' => $acme, 'date' => 'sometime', 'category' => 99999, 'amount' => 'lots', 'description' => '']);
ok($c === 422 && isset(fields($b)['date'], fields($b)['category'], fields($b)['amount'], fields($b)['description']), 'a bad date, category, amount and an empty description: 422, each its field');
[$c, $b] = record_expense($priya, $acme, '10.00', ['tax_amount' => '11.00']);
ok($c === 422 && isset(fields($b)['tax_amount']), 'tax above the amount: 422 (field tax_amount)');
[$c, $b] = record_expense($priya, $acme, '0');
ok($c === 422 && isset(fields($b)['amount']), 'an amount of zero: 422 (field amount)');
$notHers = (int) one("SELECT id FROM engagements WHERE name = 'SMOKE Not hers'") ?: (function () use ($marco) { [$c, $b] = act($marco, '/engagements/save.php', ['client' => (int) one("SELECT id FROM clients WHERE name = 'SMOKE Acme'"), 'name' => 'SMOKE Not hers', 'kind' => 'time_and_materials', 'start_now' => 'yes']); return (int) $b['record_id']; })();
$notNum = (string) one('SELECT number FROM engagements WHERE id = :e', ['e' => $notHers]);
[$c, $b] = record_expense($priya, $notHers, '10.00');
ok($c === 422 && msg($b) === 'Not staffed on ' . $notNum . ' on ' . date('Y-m-d') . ' (or the engagement is not active)', 'an engagement she is not staffed on: the database\'s sentence (' . msg($b) . ')');
[$c, $d] = screen($priya, '/expenses/new');
ok($c === 200 && in_array($acme, array_column($d['engagements'], 'engagement_id'), true) && !in_array($notHers, array_column($d['engagements'], 'engagement_id'), true) && count($d['categories']) >= 8 && $d['receipt_threshold'] === '75.00' && $d['may_set_markup'] === false, 'the form lists her engagements (staffed today), the categories, the threshold; no markup right');
[$c, $b] = record_expense($priya, $acme, '12.00', ['member' => 30]);
ok($c === 403 && msg($b) === 'You may not record expenses for that person on that engagement.', 'Priya may not record for Dana: 403 in words');
$since = last_activity_id();
[$c, $b] = record_expense($marco, $acme, '30.00', ['member' => 30, 'description' => 'SMOKE for Dana']);
$e5 = (int) ($b['record_id'] ?? 0);
ok($c === 200 && (int) expense_row($e5)['member_id'] === 30 && (int) expense_row($e5)['created_by'] === 27 && json_decode((string) activity('expense.save', $since)[0]['after'], true)['recorded_by'] === 27, 'Marco records 30.00 for Dana: the expense is hers, created_by and the log say Marco');
[$c, $b] = act($priya, '/expenses/delete.php', ['expense' => $e5]);
ok($c === 404, 'Dana\'s expense is not Priya\'s to see: delete → 404');
[$c, $b] = act($marco, '/expenses/delete.php', ['expense' => $e5]);
ok($c === 200 && (int) one('SELECT count(*) FROM expenses WHERE id = :e', ['e' => $e5]) === 0, 'her manager removes the draft (own or manage)');
$since = last_activity_id();
[$c, $b] = record_expense($priya, $acme, '15.00', ['description' => 'SMOKE to delete']);
$e6 = (int) $b['record_id'];
upload($priya, '/engagements/attachments/save.php', ['record_type' => 'expense', 'record' => $e6], 'file', jpeg_file(), 'gone.jpg');
$files = receipt_files();
[$c, $b] = act($priya, '/expenses/delete.php', ['expense' => $e6]);
$del = activity('expense.delete', $since);
ok($c === 200 && (int) one('SELECT count(*) FROM expenses WHERE id = :e', ['e' => $e6]) === 0 && (int) one("SELECT count(*) FROM attachments WHERE record_type = 'expense' AND record_id = :e", ['e' => $e6]) === 0 && receipt_files() === $files - 1 && count($del) === 1 && (int) $del[0]['engagement_id'] === $acme, 'deleting a draft takes its receipt (row and file) with it; expense.delete logged with the engagement');
[$c, $b] = act($priya, '/expenses/delete.php', ['expense' => $e1]);
ok($c === 422 && msg($b) === 'Expense EXP-000001 is submitted and is never deleted', 'a submitted expense is never deleted: the trigger\'s words');
[$c, $b] = act($dana, '/expenses/submit.php', ['expense' => $e1]);
ok($c === 404, 'Dana cannot even see Priya\'s expense: submit → 404');
finish();
